{
  "requirements": [
    {
      "text": "The ATM system shall minimize energy consumption by optimizing transaction processing to reduce idle states.",
      "kaos_level": "tactical",
      "rationale": "Reducing energy consumption directly contributes to sustainability by lowering the operational carbon footprint."
    },
    {
      "text": "The ATM system shall provide a carbon footprint report for each transaction executed.",
      "kaos_level": "operational",
      "rationale": "Tracking the carbon footprint of transactions helps the bank assess and improve its sustainability performance."
    },
    {
      "text": "The ATM system shall utilize energy-efficient hardware components to operate.",
      "kaos_level": "tactical",
      "rationale": "Using energy-efficient hardware reduces the overall energy consumption and lifecycle resource impact."
    },
    {
      "text": "The ATM system shall ensure that all recorded transactions are logged in a way that minimizes data storage requirements.",
      "kaos_level": "operational",
      "rationale": "Efficient data storage practices reduce resource impact associated with server maintenance and energy usage."
    },
    {
      "text": "The ATM system shall provide an option for clients to receive electronic transaction records instead of paper receipts.",
      "kaos_level": "operational",
      "rationale": "Encouraging electronic records reduces paper waste and supports sustainability initiatives."
    },
    {
      "text": "The ATM system shall automatically shut down during periods of inactivity to save energy.",
      "kaos_level": "tactical",
      "rationale": "Automatic shutdown during inactivity helps conserve energy, contributing to overall sustainability goals."
    },
    {
      "text": "The ATM system shall assess the environmental impact of its operations annually and report findings to stakeholders.",
      "kaos_level": "strategic",
      "rationale": "Regular assessments of environmental impact promote transparency and continuous improvement in sustainability practices."
    }
  ]
}
